import { afterEach, expect, it, vi } from 'vitest';
import { ModelRuntime } from '@earendil-works/pi-coding-agent';
import { spawn } from 'node:child_process';
import { PiMappingAgentRuntime } from '../../../mapping/agents/selection/agentRuntime';
import { PiDiagramEditRuntime } from '../../../mapping/agents/diagram-edit/diagramEditRuntime';
import { PiFileCompactionRuntime } from '../../../mapping/agents/compaction/fileCompactionRuntime';
import { CodexLocalChatRuntime } from '../../../mapping/agents/chat/localChatRuntime';

vi.mock('node:child_process', async importOriginal => ({
  ...await importOriginal<typeof import('node:child_process')>(), spawn: vi.fn()
}));
afterEach(() => vi.restoreAllMocks());

it('denies every real AI entry point by default before reading inputs or creating resources', async () => {
  const createModel = vi.spyOn(ModelRuntime, 'create');
  const selection = new PiMappingAgentRuntime();
  const edit = new PiDiagramEditRuntime('/tmp');
  const compaction = new PiFileCompactionRuntime();
  const chat = new CodexLocalChatRuntime();
  const disabled = { code: 'ai-disabled', message: expect.stringContaining('--pi') };
  await expect(selection.promptDiagramSelection(undefined!)).rejects.toMatchObject(disabled);
  await expect(edit.generate(undefined!, undefined!)).rejects.toMatchObject(disabled);
  await expect(compaction.openSession(undefined!)).rejects.toMatchObject(disabled);
  await expect(chat.reply(undefined!, undefined!)).rejects.toMatchObject(disabled);
  expect(createModel).not.toHaveBeenCalled();
  expect(spawn).not.toHaveBeenCalled();
  selection.dispose(); edit.dispose(); compaction.dispose(); chat.dispose();
});

it('denies selection requests even when a cached session is available', async () => {
  const runtime = new PiMappingAgentRuntime();
  const prompt = vi.fn();
  // Exercise the session reuse path: no model setup would be needed to spend credits.
  const sessions = (runtime as unknown as { mappingPocSessions: Map<string, unknown> }).mappingPocSessions;
  sessions.set('cached', { session: { prompt, abort: vi.fn(), dispose: vi.fn() } });
  await expect(runtime.promptDiagramSelection({ clientSessionId: 'cached' } as Parameters<typeof runtime.promptDiagramSelection>[0]))
    .rejects.toMatchObject({ code: 'ai-disabled' });
  expect(prompt).not.toHaveBeenCalled();
  sessions.clear(); runtime.dispose();
});

import { requireAiEnabled } from '../../../application/core/errors';
import type { AgentContext } from '../../../domain/core/agents/agentContext';
import { type Model } from "@earendil-works/pi-ai";
import { createAgentSession, SessionManager, type CreateAgentSessionOptions, ModelRuntime, type AgentSessionEvent } from "@earendil-works/pi-coding-agent";
import { DEFAULT_DIAGRAM_MODEL_ID, type AgentProgress } from "../../../domain/core/records/domain";
export function progressFor(event: AgentSessionEvent, model: string, sessionId: string): AgentProgress | undefined {
  const shared = { model, sessionId };
  if (event.type === "agent_start" || event.type === "turn_start" || event.type === "message_start") {
    return { ...shared, status: "generating", message: "agent is composing a structured result" };
  }
  if (event.type === "tool_execution_start") {
    if (["read", "grep", "find", "ls"].includes(event.toolName)) {
      return { ...shared, status: "reading-context", message: `inspecting source with ${event.toolName}` };
    }
    if (event.toolName.startsWith("submit_")) {
      return { ...shared, status: "validating", message: "validating structured submission" };
    }
  }
  return undefined;
}
export class PiAgentRuntime {
  constructor(private readonly enabled = false) {}

  protected requireEnabled(): void { requireAiEnabled(this.enabled); }

  protected modelRuntime?: Promise<ModelRuntime>;

  protected readonly sessions = new Set<{ abort(): Promise<void>; dispose(): void }>();

  protected async createSession(configuration: Omit<CreateAgentSessionOptions, 'sessionManager'>, context?: AgentContext) {
    this.requireEnabled();
    const sessionManager = SessionManager.inMemory(configuration.cwd);
    for (const message of context?.toPiMessages() ?? []) sessionManager.appendMessage(message);
    const result = await createAgentSession({ ...configuration, sessionManager });
    this.sessions.add(result.session);
    return result;
  }

  protected runtime(): Promise<ModelRuntime> {
    this.requireEnabled();
    this.modelRuntime ??= ModelRuntime.create({ allowModelNetwork: false });
    return this.modelRuntime;
  }

  protected async model(overrideModelId?: string): Promise<{
    runtime: ModelRuntime;
    model: Model<any>;
    provider: string;
    modelId: string;
  }> {
    const runtime = await this.runtime();
    const provider = "openai-codex";
    const modelId = overrideModelId || process.env.NEW_DIAGRAM_MODEL || DEFAULT_DIAGRAM_MODEL_ID;
    const model = runtime.getModel(provider, modelId);
    if (!model) throw new Error(`Pi model is unavailable: ${provider}/${modelId}`);
    if (!runtime.hasConfiguredAuth(provider)) {
      throw new Error(`Pi provider is not authenticated: ${provider}`);
    }
    return { runtime, model, provider, modelId };
  }
  dispose(): void {
    for (const session of this.sessions) { void session.abort(); session.dispose(); }
    this.sessions.clear();
  }
}

