import assert from 'node:assert/strict';
import { spawn } from 'node:child_process';
import { mkdtemp, rm, readFile } from 'node:fs/promises';
import { tmpdir, homedir } from 'node:os';
import { createServer } from 'node:net';
import path from 'node:path';
import { pathToFileURL } from 'node:url';
import { randomUUID } from 'node:crypto';
import { Client } from '@modelcontextprotocol/sdk/client/index.js';
import { StdioClientTransport } from '@modelcontextprotocol/sdk/client/stdio.js';
import { seedMappingFixture } from '../support/browser-mapping-fixture.mjs';
const { evaluate, waitFor, waitForSelector, withHeadlessBrowser, captureScreenshot } = await import(pathToFileURL(path.join(homedir(), '.codex/skills/front-end/browser-test.mjs')).href);
const root = await mkdtemp(path.join(tmpdir(), 'agent-diagramming-'));
let server, client;
try {
  await seedMappingFixture(root, { ascii: '[Existing]', nodes: [] });
  const port = await new Promise(resolve => { const socket = createServer(); socket.listen(0, '127.0.0.1', () => { const port = socket.address().port; socket.close(() => resolve(port)); }); });
  const url = `http://127.0.0.1:${port}`;
  server = spawn(process.execPath, ['scripts/dev/start-server.mjs', '--http', 'preview', '--host', '127.0.0.1', '--port', String(port), '--strictPort'],
    { cwd: process.cwd(), env: { ...process.env, NEW_DIAGRAM_PROJECT_ROOT: root, NEW_DIAGRAMS_DIR: path.join(root, '.diagrams'), NEW_DIAGRAM_AGENT: 'fake' }, stdio: ['ignore','ignore','pipe'] });
  let errors = ''; server.stderr.on('data', chunk => { errors += chunk; });
  await waitFor(async () => (await fetch(url).catch(() => null))?.ok, { timeoutMs: 20000 }).catch(error => { throw new Error(`${error}\n${errors}`); });
  client = new Client({ name: 'mapping-browser-check', version: '1' });
  await client.connect(new StdioClientTransport({ command: process.execPath, args: ['node_modules/tsx/dist/cli.mjs','scripts/mapping/mcp.ts',url], cwd: process.cwd(), stderr: 'pipe' }));
  const call = async (name, args, error = false) => {
    console.log('MCP call', name, args.code?.slice(0, 70) ?? args.operation ?? '');
    const result = await client.callTool({ name, arguments: args });
    console.log('MCP result', name, result.isError ? 'error' : 'ok');
    const value = JSON.parse(result.content[0].text);
    assert.equal(Boolean(result.isError), error, JSON.stringify(value));
    return value;
  };
  const exec = args => call('exec', { requestId: randomUUID(), ...args });
  assert.deepEqual((await client.listTools()).tools.map(tool => tool.name).sort(), ['accept_diagram_change_session','cancel-diagram-edit','canvas-api-search','create_diagram_change_session','diagram-search','draw_diagram','edit-diagram','edit-diagram-status','exec','save_diagram','set_diagram_source_mappings','update_diagram_change_session']);
  assert.ok((await call('canvas-api-search', { query: 'move' })).some(method => method.name === 'nodes.move'));
  assert.ok((await call('canvas-api-search', { query: 'copyDocument' })).some(method => method.name === 'canvas.copyDocument'));
  await withHeadlessBrowser({ url: `${url}/mapping`, width: 1800, height: 1100, chromePath: process.env.CHROME_PATH, arguments: ['--disable-gpu', ...(process.platform === 'linux' ? ['--no-sandbox'] : [])] }, async ({ cdp }) => {
    const send = cdp.send.bind(cdp);
    cdp.send = (method, params) => {
      let timer;
      return Promise.race([send(method, params), new Promise((_, reject) => { timer = setTimeout(() => reject(new Error(`CDP timeout: ${method}`)), 15000); })]).finally(() => clearTimeout(timer));
    };
    await cdp.send('Page.enable');
    cdp.on('Page.javascriptDialogOpening', () => void cdp.send('Page.handleJavaScriptDialog', {accept:true}));
    await waitForSelector(cdp, '[data-grid-box="overview"]');
    let available;
    await waitFor(async () => { available = (await exec({code:'return canvas.list();'})).value; return available[0]?.documents.length; });
    const canvas = available[0];
    const attached = (await exec({ code: `return canvas.attach(${JSON.stringify({canvasId:canvas.canvasId,documentId:canvas.documents[0].documentId})});` })).value;
    const sessionId = attached.sessionId;
    const before = (await exec({ sessionId, code: 'return nodes.list();' })).value;
    const args = { sessionId, requestId: randomUUID(), expectedVersion: before.version, ascii: 'Agent service\n+-- Read\n`-- Write', structureKind: 'tree', position: { column: 0, row: 0 } };
    const drawn = await call('draw_diagram', args);
    const node = drawn.nodes.find(node => node.kind === 'diagram' && node.content.ascii.startsWith('Agent service'));
    assert.ok(node);
    assert.equal(node.apiFormatVersion, 1);
    assert.ok(!('contentNodes' in node));
    assert.ok(!('content' in node.diagram));
    assert.ok(Object.keys(node.content.structure.nodes).every(id => id.startsWith('@')));
    const boxId = node.boxId;
    await waitForSelector(cdp, `[data-grid-box="${boxId}"]`);
    assert.ok(await evaluate(cdp, 'Number(document.querySelector("[data-grid-box=overview]").dataset.gridColumn) > 0'));
    assert.deepEqual(await call('draw_diagram', args), drawn);
    assert.equal(await evaluate(cdp, `document.querySelectorAll('[data-grid-box="${boxId}"]').length`), 1);
    const read = await call('diagram-search', { operation:'read', sessionId, nodeId:node.id });
    assert.equal(read.node.content.ascii, args.ascii);
    assert.equal(read.node.content.structure.kind, 'tree');
    const stale = await call('draw_diagram', { ...args, requestId: randomUUID() }, true);
    assert.match(stale.error, /VERSION_CONFLICT/);
    const partial = await call('exec', { sessionId, expectedVersion: read.version, requestId: randomUUID(), code: 'nodes.draw({ascii:"Committed before error"}); throw new Error("stop");' }, true);
    assert.match(partial.error, /stop/);
    assert.equal((await exec({ sessionId, code:'return nodes.list();' })).value.nodes.filter(node => node.kind === 'diagram').length, 3);
    const click = async selector => {
      const p = await evaluate(cdp, `(() => {const r=document.querySelector(${JSON.stringify(selector)}).getBoundingClientRect();return {x:r.left+r.width/2,y:r.top+r.height/2};})()`);
      await cdp.send('Input.dispatchMouseEvent', {type:'mousePressed', ...p, button:'left', buttons:1, clickCount:1});
      await cdp.send('Input.dispatchMouseEvent', {type:'mouseReleased', ...p, button:'left', buttons:0, clickCount:1});
    };
    await click('.mapping-grid-tools button:first-child');
    await waitFor(async () => !(await evaluate(cdp, `document.querySelector('.mapping-poc-ascii')?.textContent.includes('Committed before error')`)));
    await click('.mapping-grid-tools button:first-child');
    await waitFor(async () => !(await evaluate(cdp, `Boolean(document.querySelector('[data-grid-box="${boxId}"]'))`)));
    await click('.mapping-grid-tools button:nth-child(2)');
    await waitForSelector(cdp, `[data-grid-box="${boxId}"]`);
    const batchVersion = (await exec({sessionId,code:'return nodes.list();'})).version;
    const batch = await exec({sessionId, expectedVersion:batchVersion, code:'const a = nodes.draw({ascii:"[Batch A]",position:{column:30,row:10}}); const b = nodes.draw({ascii:"[Batch B]",position:{column:45,row:10}}); return [nodes.get({nodeId:a.id}).id,b.id];'});
    assert.equal(batch.value.length, 2);
    for (const id of batch.value) await waitForSelector(cdp, `[data-grid-box="${id.slice(5)}"]`);
    await click('.mapping-grid-tools button:first-child');
    await waitFor(async () => !(await evaluate(cdp, `Boolean(document.querySelector('[data-grid-box="${batch.value[1].slice(5)}"]'))`)));
    assert.ok(await evaluate(cdp, `Boolean(document.querySelector('[data-grid-box="${batch.value[0].slice(5)}"]'))`));
    await click('.mapping-grid-tools button:first-child');
    await waitFor(async () => !(await evaluate(cdp, `Boolean(document.querySelector('[data-grid-box="${batch.value[0].slice(5)}"]'))`)));
    assert.equal((await exec({sessionId,code:'return nodes.list();'})).value.nodes.filter(node => node.kind === 'diagram').length, 2);
    const version = (await exec({sessionId,code:'return nodes.list();'})).version;
    const saved = await call('save_diagram', {sessionId, requestId:randomUUID(), expectedVersion:version, nodeId:node.id, name:'Agent proposal'});
    await waitForSelector(cdp, `[data-project-diagram="${saved.representationId}"]`);
    const found = await call('diagram-search', {operation:'search',mode:'node',query:'Read'});
    assert.ok(found.hits.some(hit => hit.representationId === saved.representationId));
    const persisted = await call('diagram-search', {operation:'read',representationId:saved.representationId});
    assert.equal(persisted.revision.ascii, args.ascii);
    assert.equal(persisted.revision.content.kind, 'canvas-history');
    const history = persisted.revision.content.history;
    const overviewRevision = history.snapshots[history.headId].diagramBindings.overview;
    assert.equal(history.diagramRevisions[overviewRevision].diagram.content.ascii, args.ascii);
    const created = (await exec({code:`return canvas.createDocument(${JSON.stringify({canvasId:canvas.canvasId,name:'Unsaved proposal'})});`})).value;
    await waitFor(async () => (await exec({sessionId:created.sessionId,code:'return nodes.list();'})).value.nodes.length > 0);
    const replaced = await call('draw_diagram', {sessionId:created.sessionId,requestId:randomUUID(),expectedVersion:created.version,nodeId:'grid:overview',ascii:'[New document]'});
    const savedDoc = await call('save_diagram', {sessionId:created.sessionId,requestId:randomUUID(),expectedVersion:replaced.version,name:'Saved proposal'});
    await waitForSelector(cdp, `[data-project-diagram="${savedDoc.representationId}"]`);
    const sourceVersion = (await exec({sessionId:created.sessionId,code:'return nodes.list();'})).version;
    const copyAscii = 'Unsaved source\n\n`-- Keep blank separator';
    const prepared = await exec({sessionId:created.sessionId,expectedVersion:sourceVersion,code:`
      nodes.replace({nodeId:'grid:overview',ascii:${JSON.stringify(copyAscii)},structureKind:'tree'});
      const other=nodes.draw({ascii:'Related diagram',position:{column:40,row:8}});
      const source=nodes.get({nodeId:'grid:overview'});
      edges.create({source:{kind:'content-node',displayNodeId:source.id,contentNodeId:Object.values(source.content.structure.nodes)[0].id,revisionId:source.content.revisionId},
        target:{kind:'box',displayNodeId:other.id},appearance:{color:'#88c0d0',lineStyle:'solid',label:{text:'Related',position:{x:250,y:80}}}});
      return {nodes:nodes.list(),edges:edges.list()};`});
    const copyRequest = {requestId:randomUUID(),code:`return canvas.copyDocument(${JSON.stringify({canvasId:canvas.canvasId,documentId:created.documentId,name:'Independent copy',expectedVersion:prepared.transaction.version})});`};
    const copyResult = await exec(copyRequest), copy = copyResult.value;
    assert.deepEqual(await exec(copyRequest), copyResult);
    assert.notEqual(copy.documentId, created.documentId); assert.equal(copy.version, 0);
    await waitFor(async () => await evaluate(cdp, `document.querySelector('.mapping-document-view:not([hidden]) [data-native-node="grid:overview"] .mapping-poc-ascii')?.textContent.includes("Unsaved source")`));
    await waitFor(async () => await evaluate(cdp, 'document.querySelector(".mapping-document-view:not([hidden]) .mapping-grid-tools button:first-child")?.disabled'));
    const copiedState = (await exec({sessionId:copy.sessionId,code:'return {nodes:nodes.list(),edges:edges.list()};'})).value;
    const contents = state => state.nodes.nodes.filter(n=>n.kind==='diagram').map(n=>({id:n.id,content:n.content}));
    assert.deepEqual(contents(copiedState), contents(prepared.value));
    assert.deepEqual(copiedState.edges.edges, prepared.value.edges.edges);
    assert.equal(copiedState.nodes.nodes.find(n=>n.id==='grid:overview').content.ascii, copyAscii);
    await exec({sessionId:copy.sessionId,expectedVersion:0,code:'return nodes.replace({nodeId:"grid:overview",ascii:"Changed only in copy"});'});
    await waitFor(async () => await evaluate(cdp, `document.querySelector('.mapping-document-view:not([hidden]) [data-native-node="grid:overview"] .mapping-poc-ascii')?.textContent.includes("Changed only in copy")`));
    await click('.mapping-document-view:not([hidden]) .mapping-grid-tools button:first-child');
    await waitFor(async () => await evaluate(cdp, `document.querySelector('.mapping-document-view:not([hidden]) [data-native-node="grid:overview"] .mapping-poc-ascii')?.textContent.includes("Unsaved source")`));
    await click('.mapping-document-view:not([hidden]) .mapping-grid-tools button:nth-child(2)');
    await waitFor(async () => await evaluate(cdp, `document.querySelector('.mapping-document-view:not([hidden]) [data-native-node="grid:overview"] .mapping-poc-ascii')?.textContent.includes("Changed only in copy")`));
    const sourceAfter = (await exec({sessionId:created.sessionId,code:'return {nodes:nodes.list(),edges:edges.list()};'})).value;
    assert.deepEqual(sourceAfter, prepared.value);
    const copyVersion = (await exec({sessionId:copy.sessionId,code:'return nodes.list();'})).version;
    const savedCopy = await call('save_diagram', {sessionId:copy.sessionId,requestId:randomUUID(),expectedVersion:copyVersion,name:'Independent copy'});
    assert.notEqual(savedCopy.representationId, savedDoc.representationId);
    await waitForSelector(cdp, `[data-project-diagram="${savedCopy.representationId}"]`);
    const savedSource = await call('diagram-search', {operation:'read',representationId:savedDoc.representationId});
    assert.equal(savedSource.revision.ascii, '[New document]');
    await captureScreenshot(cdp, {output:path.join(root,'agent-diagramming.png')});
    let reloaded = false;
    cdp.on('Page.loadEventFired', () => { reloaded = true; });
    await cdp.send('Page.reload');
    await waitFor(() => reloaded);
    await waitFor(async () => await evaluate(cdp, `document.querySelector('.mapping-document-view:not([hidden]) [data-native-node="grid:overview"] .mapping-poc-ascii')?.textContent.includes("Changed only in copy")`));
    // Workspace restore selects its saved active document. Use the explorer to switch to the source.
    await click(`[data-project-diagram="${savedDoc.representationId}"]`);
    await waitFor(async () => await evaluate(cdp, `document.querySelector('.mapping-document-view:not([hidden]) [data-native-node="grid:overview"] .mapping-poc-ascii')?.textContent.includes("Unsaved source")`));
    await click(`[data-project-diagram="${savedCopy.representationId}"]`);
    await waitFor(async () => await evaluate(cdp, `document.querySelector('.mapping-document-view:not([hidden]) [data-native-node="grid:overview"] .mapping-poc-ascii')?.textContent.includes("Changed only in copy")`));
    const catalog = JSON.parse(await readFile(path.join(root,'.diagrams/canvases/catalog.json'),'utf8'));
    assert.equal(catalog.representations[savedDoc.representationId].status, 'settled');
    console.log('MCP search/read, draw, layout, retry, conflict, partial failures, per-edit undo/redo, standalone save, document copy with unsaved content/blank lines/edges, independent undo/save, explorer, and reload passed');
  });
} finally {
  await client?.close(); server?.kill('SIGTERM'); await rm(root,{recursive:true,force:true});
}

sources.tests/browser/mapping/browser-canvas-pas:
import assert from 'node:assert/strict';
import { spawn } from 'node:child_process';
import { mkdtemp, rm } from 'node:fs/promises';
import { tmpdir, homedir } from 'node:os';
import { createServer } from 'node:net';
import path from 'node:path';
import { pathToFileURL } from 'node:url';
import { seedMappingFixture } from '../support/browser-mapping-fixture.mjs';
const { evaluate, waitFor, waitForSelector, withHeadlessBrowser, captureScreenshot } = await import(pathToFileURL(path.join(homedir(), '.codex/skills/front-end/browser-test.mjs')).href);
const root = await mkdtemp(path.join(tmpdir(), 'canvas-paste-'));
let server;
const ascii = 'Workbench renderer\n|-- EditorPart\n`-- View\n   \nEnd';
try {
  await seedMappingFixture(root, { ascii, nodes: [] });
  const port = await new Promise(resolve => { const s = createServer(); s.listen(0, '127.0.0.1', () => { const p = s.address().port; s.close(() => resolve(p)); }); });
  const url = `http://127.0.0.1:${port}`;
  server = spawn(process.execPath, ['scripts/dev/start-server.mjs', '--http', 'preview', '--host', '127.0.0.1', '--port', String(port), '--strictPort'],
    { cwd: process.cwd(), env: { ...process.env, NEW_DIAGRAM_PROJECT_ROOT: root, NEW_DIAGRAMS_DIR: path.join(root, '.diagrams'), NEW_DIAGRAM_AGENT: 'fake' }, stdio: 'ignore' });
  await waitFor(async () => (await fetch(url).catch(() => null))?.ok, { timeoutMs: 20000 });
  await withHeadlessBrowser({ url: `${url}/mapping`, width: 1800, height: 1100, chromePath: process.env.CHROME_PATH, arguments: ['--disable-gpu', ...(process.env.CHROME_PATH ? ['--no-sandbox'] : [])] }, async ({ cdp }) => {
    const send = cdp.send.bind(cdp);
    cdp.send = (method, params) => {
      let timer;
      return Promise.race([send(method, params), new Promise((_, reject) => { timer = setTimeout(() => reject(new Error(`CDP timeout: ${method}`)), 15000); })]).finally(() => clearTimeout(timer));
    };
    const click = async selector => {
      const point = typeof selector === 'string' ? await evaluate(cdp, `(() => { const r = document.querySelector(${JSON.stringify(selector)}).getBoundingClientRect(); return {x: r.left + r.width/2, y: r.top + r.height/2}; })()`) : selector;
      await cdp.send('Input.dispatchMouseEvent', { type: 'mousePressed', ...point, button: 'left', buttons: 1, clickCount: 1 });
      await cdp.send('Input.dispatchMouseEvent', { type: 'mouseReleased', ...point, button: 'left', clickCount: 1 });
    };
    const key = async (key, code, windowsVirtualKeyCode) => {
      await cdp.send('Input.dispatchKeyEvent', { type: 'keyDown', key, code, windowsVirtualKeyCode });
      await cdp.send('Input.dispatchKeyEvent', { type: 'keyUp', key, code, windowsVirtualKeyCode });
    };
    const count = () => evaluate(cdp, 'document.querySelectorAll("[data-grid-box]").length');
    const gridPoint = (column, row) => evaluate(cdp, `(() => {
      const box = document.querySelector('[data-grid-box="overview"]'), r = box.getBoundingClientRect();
      const w = r.width / Number(box.dataset.gridColumns), h = r.height / Number(box.dataset.gridRows);
      return {x: r.left + (${column} - Number(box.dataset.gridColumn) + .5) * w,
        y: r.top + (${row} - Number(box.dataset.gridRow) + .5) * h};
    })()`);
    const rightClick = async point => {
      await cdp.send('Input.dispatchMouseEvent', {type:'mousePressed', ...point, button:'right', buttons:2, clickCount:1});
      await cdp.send('Input.dispatchMouseEvent', {type:'mouseReleased', ...point, button:'right', buttons:0, clickCount:1});
    };
    const clipboard = text => evaluate(cdp, `Object.defineProperty(navigator, 'clipboard', {configurable:true, value:{readText:async () => ${JSON.stringify(text)}}})`);
    const open = async (column, row) => {
      await rightClick(await gridPoint(column, row));
      await waitForSelector(cdp, '.canvas-paste-menu');
    };
    const pastedBox = () => evaluate(cdp, `Array.from(document.querySelectorAll('[data-grid-box]')).filter(el => !['root','overview'].includes(el.dataset.gridBox)).map(el => ({id:el.dataset.gridBox, column:Number(el.dataset.gridColumn), row:Number(el.dataset.gridRow)}))`);
    await waitForSelector(cdp, '[data-grid-box="overview"]');
    await waitFor(async () => await evaluate(cdp, `document.querySelector('.diagram-canvas__surface')?.style.transform.includes('translate3d(')`));
    const initialCount = await count();
    await open(25, 7); // Blank canvas, without any selection or entities.
    await cdp.send('Page.enable');
    await captureScreenshot(cdp, {output:path.join(root, 'paste-menu.png')});
    await key('Escape','Escape',27);
    await waitFor(async () => await evaluate(cdp, '!document.querySelector(".canvas-paste-menu")'));
    await open(25, 7);
    await click({x:10,y:10});
    await waitFor(async () => await evaluate(cdp, '!document.querySelector(".canvas-paste-menu")'));

    console.log('Menu dismissal passed');
    // Real pan and zoom, followed by an insertion at known grid coordinates.
    const pan = await gridPoint(30, 10);
    await cdp.send('Input.dispatchMouseEvent', {type:'mousePressed', ...pan, button:'left', buttons:1});
    await cdp.send('Input.dispatchMouseEvent', {type:'mouseMoved', x:pan.x+60, y:pan.y+40, button:'left', buttons:1});
    await cdp.send('Input.dispatchMouseEvent', {type:'mouseReleased', x:pan.x+60, y:pan.y+40, button:'left', buttons:0});
    await cdp.send('Input.dispatchMouseEvent', {type:'mouseWheel', ...pan, deltaX:0, deltaY:-150, modifiers:2});
    await waitFor(async () => await evaluate(cdp, 'document.querySelector(".diagram-canvas__controls output")?.value !== "100%"'));
    await clipboard('```text\r\n  Pasted\r\n  |-- Child\r\n```');
    await open(25, 7);
    await click('.canvas-paste-menu button');
    await waitFor(async () => (await count()) === initialCount + 1);
    assert.deepEqual((await pastedBox()).map(({column,row}) => ({column,row})), [{column:25,row:7}]);
    assert.match(await evaluate(cdp, 'document.querySelector(".mapping-poc-ascii").textContent'), /Pasted/);
    await click('.mapping-grid-tools button:first-child');
    await waitFor(async () => (await count()) === initialCount);
    await click('.mapping-grid-tools button:nth-child(2)');
    await waitFor(async () => (await count()) === initialCount + 1);
    assert.equal((await pastedBox())[0].column, 25);

    console.log('Placement and undo/redo passed');
    // Overlap anchors the paste and moves the old diagram to the right.
    await clipboard('[Overlap]');
    await open(0, 0);
    await click('.canvas-paste-menu button');
    await waitFor(async () => (await count()) === initialCount + 2);
    assert.ok(await evaluate(cdp, 'Number(document.querySelector("[data-grid-box=overview]").dataset.gridColumn) >= 12'));
    assert.ok((await pastedBox()).some(box => box.column === 0 && box.row === 0));

    console.log('Collision passed');
    // Invalid/empty data creates no box and exposes a manual paste form.
    await clipboard('   ');
    await open(25, 12);
    await click('.canvas-paste-menu button');
    await waitForSelector(cdp, '.canvas-paste-menu [role=alert]');
    assert.equal(await count(), initialCount + 2);
    assert.equal(await evaluate(cdp, 'document.querySelector(".canvas-paste-menu button").disabled'), true);
    await key('Escape','Escape',27);
    await evaluate(cdp, `Object.defineProperty(navigator, 'clipboard', {configurable:true, value:{readText:async () => {throw new Error('denied')}}})`);
    await open(25, 12);
    await click('.canvas-paste-menu button');
    await waitForSelector(cdp, '.canvas-paste-menu textarea');
    await click('.canvas-paste-menu textarea');
    await cdp.send('Input.insertText', {text:'[Manual]'});
    await click('.canvas-paste-menu button');
    await waitFor(async () => (await count()) === initialCount + 3);

    console.log('Fallback passed');
    // Slow clipboard reads cannot duplicate insertions or outlive cancellation.
    await evaluate(cdp, `Object.defineProperty(navigator, 'clipboard', {configurable:true, value:{readText:() => {window.__reads=(window.__reads||0)+1; return new Promise(resolve => window.__resolveClipboard=resolve)}}})`);
    await open(25, 16);
    await click('.canvas-paste-menu button');
    await click('.canvas-paste-menu button');
    assert.equal(await evaluate(cdp, 'window.__reads'), 1);
    await key('Escape','Escape',27);
    await evaluate(cdp, 'window.__resolveClipboard("[Too late]")');
    await evaluate(cdp, 'new Promise(resolve => requestAnimationFrame(() => requestAnimationFrame(resolve)))');
    assert.equal(await count(), initialCount + 3);
    await open(25, 16);
    await click('.canvas-paste-menu button');
    await click('.mapping-submenu button');
    await waitFor(async () => await evaluate(cdp, '!document.querySelector(".canvas-paste-menu")'));
    await waitForSelector(cdp, '.mapping-create-dialog');
    await evaluate(cdp, 'window.__resolveClipboard("[Also too late]")');
    await evaluate(cdp, 'new Promise(resolve => requestAnimationFrame(() => requestAnimationFrame(resolve)))');
    assert.equal(await count(), initialCount + 3);

    // A real right-click inside a text field keeps the native menu.
    await evaluate(cdp, `window.addEventListener('contextmenu', event => { window.__nativeContextPrevented = event.defaultPrevented; }, {once:true})`);
    const field = await evaluate(cdp, `(() => { const r=document.querySelector('.mapping-create-dialog input').getBoundingClientRect(); return {x:r.left+r.width/2,y:r.top+r.height/2}; })()`);
    await rightClick(field);
    assert.equal(await evaluate(cdp, 'window.__nativeContextPrevented'), false);
    await key('Escape', 'Escape', 27);
    // Escape may dismiss the dialog as well as the native context menu.
    if (await evaluate(cdp, '!!document.querySelector(".mapping-create-dialog")')) await click('.mapping-create-dialog footer button:first-child');
    await waitFor(async () => await evaluate(cdp, '!document.querySelector(".mapping-create-dialog")'));
    await waitFor(async () => {
      const workspace = await (await fetch(`${url}/api/mapping/workspace`)).json();
      return Object.values(workspace?.documents[0]?.document?.scene?.contents ?? {}).some(content => content.content.ascii === '[Manual]');
    });
    const savedWorkspace = await (await fetch(`${url}/api/mapping/workspace`)).json();
    const history = savedWorkspace.documents[0].history;
    assert.ok(history.contextId);
    assert.ok(history.past.length);
    assert.ok(!('contents' in history.snapshots[history.headId].document.scene));
    console.log('Automatic checkpoint persistence passed');
    cdp.on('Page.javascriptDialogOpening', () => void cdp.send('Page.handleJavaScriptDialog', {accept:true}));
    await cdp.send('Page.reload', {ignoreCache:true});
    await waitForSelector(cdp, '[data-grid-box="overview"]');
    await waitFor(async () => (await count()) === initialCount + 3);
    assert.match(await evaluate(cdp, 'document.querySelector(".mapping-poc-ascii").textContent'), /Manual/);
    await click('.mapping-grid-tools button:first-child');
    await waitFor(async () => (await count()) === initialCount + 2);
    await click('.mapping-grid-tools button:nth-child(2)');
    await waitFor(async () => (await count()) === initialCount + 3);
    console.log('Canvas paste passed: menu dismissal, pan/zoom coordinates, collision layout, undo/redo, clipboard validation/fallback, stale reads, and save/reload.');

  });
} finally {
  if (server && server.exitCode === null) { server.kill('SIGTERM'); await new Promise(resolve => server.once('exit', resolve)); }
  await rm(root, { recursive: true, force: true });
}

sources.tests/browser/mapping/browser-change-acc:
import assert from 'node:assert/strict';
import { spawn } from 'node:child_process';
import { mkdtemp, rm } from 'node:fs/promises';
import { tmpdir, homedir } from 'node:os';
import { createServer } from 'node:net';
import path from 'node:path';
import { pathToFileURL } from 'node:url';
import { seedMappingFixture } from '../support/browser-mapping-fixture.mjs';
import { DiagramStore } from '../../../infrastructure/core/persistence/store.ts';
import { DiagramChangeSessionStore } from '../../../infrastructure/mapping/changes/diagramChangeSessionStore.ts';
import { ChangeSessionService } from '../../../application/mapping/changes/changeSessionService.ts';
const { evaluate, waitFor, waitForSelector, withHeadlessBrowser } = await import(pathToFileURL(path.join(homedir(), '.codex/skills/front-end/browser-test.mjs')).href);
const root = await mkdtemp(path.join(tmpdir(), 'acceptance-browser-'));
let server;
try {
  // Disposable fixture setup happens before the server or browser starts.
  await seedMappingFixture(root, { ascii: 'Root\n|-- Before acceptance\n`-- Keep', nodes: [] });
  const store = new DiagramStore(root), repository = new DiagramChangeSessionStore(store.storeRoot);
  const bridge = { list: () => [] };
  const changes = new ChangeSessionService(repository, store, bridge);
  const proposal = await changes.create({ title: 'Acceptance browser fixture', requestId: 'fixture-create' });
  const changeSessionId = proposal.changeSessionId, documentId = proposal.documents[0].documentId;
  await changes.apply(changeSessionId, documentId, 0, [{ method: 'patchDiagram', nodeId: 'grid:overview', start: 2, end: 2, patch: '|-- After acceptance' }], 'fixture-edit');
  const draft = await changes.get(changeSessionId);
  await changes.update({ changeSessionId, expectedVersion: draft.version, requestId: 'fixture-ready', status: 'ready' });
  const port = await new Promise(resolve => { const socket = createServer(); socket.listen(0, '127.0.0.1', () => { const port = socket.address().port; socket.close(() => resolve(port)); }); });
  const url = `http://127.0.0.1:${port}`;
  server = spawn(process.execPath, ['scripts/dev/start-server.mjs', '--http', 'preview', '--host', '127.0.0.1', '--port', String(port), '--strictPort'],
    { cwd: process.cwd(), env: { ...process.env, NEW_DIAGRAM_PROJECT_ROOT: root, NEW_DIAGRAMS_DIR: store.storeRoot, NEW_DIAGRAM_AGENT: 'fake' }, stdio: ['ignore', 'ignore', 'pipe'] });
  let serverErrors = ''; server.stderr.on('data', chunk => { serverErrors += chunk; });
  await waitFor(async () => (await fetch(url).catch(() => null))?.ok, { timeoutMs: 20000 }).catch(error => { throw new Error(`${error}\n${serverErrors}`); });
  await withHeadlessBrowser({ url: `${url}/mapping`, width: 1800, height: 1100, chromePath: process.env.CHROME_PATH,
    arguments: ['--disable-gpu', ...(process.platform === 'linux' ? ['--no-sandbox'] : [])] }, async ({ cdp }) => {
    const send = cdp.send.bind(cdp);
    cdp.send = async (method, params) => {
      let timer;
      try { return await Promise.race([send(method, params), new Promise((_, reject) => { timer = setTimeout(() => reject(Error(`CDP timed out: ${method}`)), 30000); })]); }
      finally { clearTimeout(timer); }
    };
    const errors = [];
    await cdp.send('Page.enable');
    cdp.on('Page.javascriptDialogOpening', () => void cdp.send('Page.handleJavaScriptDialog', { accept: true }));
    await cdp.send('Runtime.enable'); cdp.on('Runtime.exceptionThrown', event => errors.push(event.exceptionDetails.text));
    const canvasReplies = [];
    const changeReads = [];
    cdp.on('Fetch.requestPaused', event => {
      changeReads.push(event.request.url);
      void cdp.send('Fetch.continueRequest', { requestId: event.requestId });
    });
    await cdp.send('Fetch.enable', { patterns: [{ urlPattern: '*/api/mapping/agent/change-sessions*' }] });
    await cdp.send('Network.enable');
    cdp.on('Network.requestWillBeSent', ({ request }) => {
      if (request.url.includes('/canvases/') && request.url.endsWith('/reply') && request.postData)
        canvasReplies.push(JSON.parse(request.postData));
    });
    const click = async (selector, text) => {
      let point;
      await waitFor(async () => {
        point = await evaluate(cdp, `(() => { const el = [...document.querySelectorAll(${JSON.stringify(selector)})].find(el => !el.disabled && ${text ? `el.textContent.includes(${JSON.stringify(text)})` : 'true'}); if (!el) return null; const r=el.getBoundingClientRect(); return r.width && r.height ? {x:r.x+r.width/2,y:r.y+r.height/2}:null; })()`);
        return !!point;
      });
      await cdp.send('Input.dispatchMouseEvent', { type: 'mousePressed', button: 'left', clickCount: 1, ...point });
      await cdp.send('Input.dispatchMouseEvent', { type: 'mouseReleased', button: 'left', clickCount: 1, ...point });
    };
    const visibleCanvasText = () => evaluate(cdp, `document.querySelector('.mapping-document-view:not([hidden])')?.textContent ?? ''`);
    await waitFor(async () => (await visibleCanvasText()).includes('Before acceptance'));
    await click('[role="tab"]', 'Changes');
    await click('nav[aria-label="Diagram changes"] summary', 'Acceptance browser fixture');
    await click('nav[aria-label="Diagram changes"] button', 'Current LLM prompt stack');
    await waitForSelector(cdp, '[data-diff-status="modified"]');
    await waitFor(() => changeReads.some(url => url.includes('/preview?')));
    assert.ok(!changeReads.some(url => url.endsWith(`/change-sessions/${changeSessionId}`)), 'Opening a preview must not request the full session');
    await waitFor(() => changeReads.some(url => url.includes('/preview?') && new URL(url).searchParams.has('version')));
    const scoped = await fetch(`${url}/api/mapping/agent/change-sessions/${changeSessionId}/preview?documentId=${documentId}`).then(r => r.json());
    assert.equal(scoped.document.id, documentId);
    assert.ok(!('history' in scoped.document) && !('past' in scoped.document) && !('receipts' in scoped));
    assert.equal(await fetch(`${url}/api/mapping/agent/change-sessions/${changeSessionId}/preview?documentId=${documentId}&version=${scoped.version}`).then(r => r.json()), null);
    console.log('Scoped preview rendered; accepting');
    canvasReplies.length = 0;
    await click('.change-session-actions button', 'Accept all changes');
    await waitFor(async () => (await visibleCanvasText()).includes('After acceptance'));
    const stateReplies = canvasReplies.filter(reply => reply.value?.document);
    assert.ok(stateReplies.length > 0, 'acceptance checked the live browser state');
    for (const reply of stateReplies)
      assert.deepEqual(Object.keys(reply.value).sort(), ['document', 'name'], 'acceptance does not transfer history or rendering metadata');
    assert.equal(await evaluate(cdp, '!!document.querySelector("[data-change-session]")'), false);
    assert.equal(await evaluate(cdp, '!!document.querySelector("[data-diff-status]")'), false);
    const accepted = await changes.get(changeSessionId);
    assert.equal(accepted.status, 'accepted');
    assert.ok(accepted.acceptance.documents[0].before.checkpointId);
    // Wait for the public workspace autosave to contain the new published head.
    await waitFor(async () => {
      const response = await fetch(`${url}/api/mapping/workspace`);
      if (!response.ok) return false;
      return JSON.stringify(await response.json()).includes(accepted.acceptance.documents[0].after.revisionId);
    });
    await cdp.send('Page.reload', { ignoreCache: true });
    console.log('Reloading accepted canvas');
    await waitFor(async () => (await visibleCanvasText()).includes('After acceptance'));
    await click('[role="tab"]', 'Changes');
    await click('nav[aria-label="Diagram changes"] summary', 'Acceptance browser fixture');
    await click('nav[aria-label="Diagram changes"] button', 'Current LLM prompt stack');
    await waitForSelector(cdp, '[data-diff-status="modified"]');
    assert.ok(await evaluate(cdp, 'document.querySelector(".change-session-actions").textContent.includes("Accepted")'));
    assert.equal(await evaluate(cdp, '[...document.querySelectorAll(".change-session-actions button")].some(b=>b.textContent.includes("Accept all"))'), false);
    const previewCount = changeReads.filter(url => url.includes('/preview?')).length;
    const listCount = changeReads.filter(url => url.endsWith('/change-sessions')).length;
    await waitFor(() => changeReads.filter(url => url.endsWith('/change-sessions')).length >= listCount + 2);
    assert.equal(changeReads.filter(url => url.includes('/preview?')).length, previewCount, 'Accepted previews stop polling while the explorer continues refreshing summaries');
    await click('.change-session-actions button', 'Open canvas');
    await waitFor(async () => (await visibleCanvasText()).includes('After acceptance'));
    await click('.mapping-document-view:not([hidden]) button', 'Undo');
    await waitFor(async () => (await visibleCanvasText()).includes('Before acceptance'));
    // Reopening the accepted review must not discard a later local undo/edit.
    await click('[role="tab"]', 'Changes');
    await click('nav[aria-label="Diagram changes"] summary', 'Acceptance browser fixture');
    await click('nav[aria-label="Diagram changes"] button', 'Current LLM prompt stack');
    await waitForSelector(cdp, '.change-session-actions');
    await click('.change-session-actions button', 'Open canvas');
    await waitFor(async () => (await visibleCanvasText()).includes('Before acceptance'));
    assert.deepEqual(errors, []);
    console.log('PASS: accept -> published canvas without diff -> reload -> retained review diff -> undo restores original');
  });
} finally {
  if (server && server.exitCode === null) {
    server.kill('SIGTERM');
    await new Promise(resolve => server.once('exit', resolve));
  }
  await rm(root, { recursive: true, force: true });
}

