    await cdp.send('Input.dispatchMouseEvent', { type: 'mouseReleased', x: canvasPoint.x + 60, y: canvasPoint.y + 30, button: 'middle', buttons: 0, clickCount: 1 });
    const compactCamera = await read('document.querySelector(".window-panel-canvas .diagram-canvas__surface").style.transform');
    await click('[aria-label="Minimize to focused pane"]');
